import type { Activity } from '@ansible/nexus-contracts'

import type { EdgeConnection } from '../types/edge'

/**
 * Shared utilities for handling parallel_for_* wrapper activities.
 * These wrappers are auto-generated by syncJoinBranches to group parallel branches
 * that converge at a join node.
 */

type ParallelActivity = Extract<Activity, { type: 'parallel' }>

/**
 * Checks if an activity is an auto-generated parallel wrapper for a join node.
 * These wrappers have IDs in the format: parallel_for_${joinId}
 */
export function isParallelWrapper(activity: Activity): activity is ParallelActivity {
  return activity.type === 'parallel' && activity.id.startsWith('parallel_for_')
}

/**
 * Extracts the join node ID from a parallel wrapper ID.
 * @example getJoinIdFromWrapper('parallel_for_J1') // returns 'J1'
 */
export function getJoinIdFromWrapper(wrapperId: string): string {
  return wrapperId.replace('parallel_for_', '')
}

/**
 * Creates a parallel wrapper ID for a given join node ID.
 * @example createWrapperIdForJoin('J1') // returns 'parallel_for_J1'
 */
export function createWrapperIdForJoin(joinId: string): string {
  return `parallel_for_${joinId}`
}

/**
 * Gets the branches from a parallel wrapper activity.
 * Returns an empty array if the activity is not a parallel or has no branches.
 */
export function getWrapperBranches(activity: Activity): Activity[] {
  if (activity.type !== 'parallel') {
    return []
  }
  return activity.branches || []
}

/**
 * Creates edges from a source node to all branches of a parallel wrapper.
 * Used when connecting condition nodes or sequential activities to parallel branches.
 *
 * @param sourceId - ID of the source node
 * @param wrapper - The parallel wrapper activity
 * @param sourceHandle - The source handle type ('true', 'false', or 'source')
 * @returns Array of edge connections to each branch
 */
export function createEdgesToWrapperBranches(
  sourceId: string,
  wrapper: ParallelActivity,
  sourceHandle: string = 'source'
): EdgeConnection[] {
  const branches = wrapper.branches || []
  return branches.map((branch) => {
    // Include sourceHandle in ID for condition nodes (true/false handles)
    const edgeId =
      sourceHandle === 'true' || sourceHandle === 'false'
        ? `${sourceId}-${sourceHandle}-${branch.id}`
        : `${sourceId}-${branch.id}`

    return {
      id: edgeId,
      source: sourceId,
      target: branch.id,
      sourceHandle,
      targetHandle: 'target',
    }
  })
}

/**
 * Creates edges from all branches of a parallel wrapper to a target node (typically a join).
 * Used when generating edges from wrapper branches back to their join node.
 *
 * @param wrapper - The parallel wrapper activity
 * @param targetId - ID of the target node (usually the join node)
 * @returns Array of edge connections from each branch to the target
 */
export function createEdgesFromWrapperBranches(wrapper: ParallelActivity, targetId: string): EdgeConnection[] {
  const branches = wrapper.branches || []
  return branches.map((branch) => ({
    id: `${branch.id}-${targetId}`,
    source: branch.id,
    target: targetId,
    sourceHandle: 'source',
    targetHandle: 'target',
  }))
}

/**
 * Finds an activity by ID, searching both top-level activities and inside parallel wrappers.
 * This is useful because activities can be nested inside parallel_for_* wrappers.
 *
 * @returns Object containing the activity and its wrapper (if inside a wrapper)
 */
export function findActivityAndWrapper(
  activityId: string,
  allActivities: Activity[]
): { activity?: Activity; wrapper?: ParallelActivity } {
  // Check top-level activities first
  const topLevel = allActivities.find((a) => a.id === activityId)
  if (topLevel) {
    return { activity: topLevel }
  }

  // Search inside parallel_for_* wrappers
  for (const activity of allActivities) {
    if (isParallelWrapper(activity)) {
      const branches = activity.branches || []
      const found = branches.find((b) => b.id === activityId)
      if (found) {
        return { activity: found, wrapper: activity }
      }
    }
  }

  return {}
}
